const grpc = require('@grpc/grpc-js');
const redis = require('../redis');
const db = require('../db');

async function subscribeDeviceTelemetry(call) {
  const deviceId = call.request.device_id;
  const userId = call.metadata.get('x-user-id')[0];

  if (!deviceId) {
    return call.destroy(new Error('Missing device_id'));
  }

  // Verify device belongs to caller's authorized customer account
  const device = await db('registered_hardware')
    .join('account_memberships', 'registered_hardware.account_id', '=', 'account_memberships.account_id')
    .where({ 'registered_hardware.id': deviceId, 'account_memberships.user_id': userId })
    .first();

  if (!device) {
    const error = new Error('Device not found or access denied');
    error.code = grpc.status.PERMISSION_DENIED;
    return call.destroy(error);
  }

  const subscriber = redis.duplicate();
  await subscriber.connect();
  subscriber.subscribe(`telemetry:device:${deviceId}`, (message) => {
    const payload = JSON.parse(message);
    call.write({
      timestamp: payload.ts,
      temperature: payload.temp,
      vibration: payload.vibe,
      status: payload.status
    });
  });

  call.on('cancelled', () => {
    subscriber.quit();
  });
}

module.exports = { subscribeDeviceTelemetry };
